using EduMark.Domain.Entities;
using Microsoft.EntityFrameworkCore;
namespace EduMark.Infrastructure.Persistence;
public sealed class EduMarkDbContext(DbContextOptions<EduMarkDbContext> options) : DbContext(options) { public DbSet<Course> Courses => Set<Course>(); public DbSet<Enrollment> Enrollments => Set<Enrollment>(); protected override void OnModelCreating(ModelBuilder m) { m.Entity<Course>(e => { e.ToTable("courses"); e.HasKey(x => x.Id); e.Property(x => x.Title).HasMaxLength(160).IsRequired(); e.Property(x => x.Slug).HasMaxLength(180).IsRequired(); e.HasIndex(x => x.Slug).IsUnique(); e.Property(x => x.Description).HasMaxLength(2000).IsRequired(); e.Property(x => x.Price).HasPrecision(18, 2); }); m.Entity<Enrollment>(e => { e.ToTable("enrollments"); e.HasKey(x => x.Id); e.Property(x => x.StudentEmail).HasMaxLength(254).IsRequired(); e.HasIndex(x => new { x.CourseId, x.StudentEmail }).IsUnique(); e.HasOne(x => x.Course).WithMany(x => x.Enrollments).HasForeignKey(x => x.CourseId).OnDelete(DeleteBehavior.Cascade); }); } }
